  "query": "// ITD-001 MFA fatigue: burst of denied or ignored MFA prompts, optionally followed by an approval\n// ATT&CK T1621 Multi-Factor Authentication Request Generation\nlet lookback = 2h;\nlet burstGap = 5m;          // denials no more than this far apart count as one burst\nlet maxBurst = 1h;          // cap on how long one burst can run\nlet minDenials = 5;         // prompts in a burst before we care\nlet approvalWindow = 30m;   // an approval this soon after the burst raises severity\nlet Denials =\n    SigninLogs\n    | where TimeGenerated > ago(lookback)\n    | where ResultType == \"500121\"   // authentication failed during strong authentication request\n    | sort by UserPrincipalName asc, TimeGenerated asc\n    | extend BurstStart = row_window_session(TimeGenerated, maxBurst, burstGap, UserPrincipalName != prev(UserPrincipalName))\n    | summarize\n        DenialCount = count(),\n        FirstDenial = min(TimeGenerated),\n        LastDenial = max(TimeGenerated),\n        DenialIPs = make_set(IPAddress, 10),\n        Apps = make_set(AppDisplayName, 10)\n        by UserPrincipalName, BurstStart\n    | where DenialCount >= minDenials;\nlet Approvals =\n    SigninLogs\n    | where TimeGenerated > ago(lookback)\n    | where ResultType == \"0\" and AuthenticationRequirement == \"multiFactorAuthentication\"\n    | project UserPrincipalName, ApprovalTime = TimeGenerated, ApprovalIP = IPAddress;\nDenials\n| join kind=leftouter Approvals on UserPrincipalName\n| extend InWindow = ApprovalTime between (FirstDenial .. (LastDenial + approvalWindow))\n| summarize\n    ApprovedAfterBurst = countif(InWindow) > 0,\n    ApprovalIPs = make_set_if(ApprovalIP, InWindow, 10)\n    by UserPrincipalName, FirstDenial, LastDenial, DenialCount, DenialIPsText = strcat_array(DenialIPs, \",\"), AppsText = strcat_array(Apps, \",\")\n| extend DenialIPs = split(DenialIPsText, \",\"), Apps = split(AppsText, \",\")\n| extend Severity = iff(ApprovedAfterBurst, \"High\", \"Medium\")\n| project FirstDenial, LastDenial, UserPrincipalName, DenialCount, DenialIPs, Apps, ApprovedAfterBurst, ApprovalIPs, Severity",
