  "query": "// ITD-002 Illicit OAuth consent: a user or admin grants an app high-risk delegated permissions\n// ATT&CK T1528 Steal Application Access Token\nlet lookback = 1d;\n// Scopes that let an app read or exfiltrate mail, files or the directory without the password\nlet highRiskScopes = dynamic([\n    \"Mail.Read\", \"Mail.ReadWrite\", \"Mail.Send\", \"MailboxSettings.ReadWrite\",\n    \"Files.Read.All\", \"Files.ReadWrite.All\", \"Sites.Read.All\", \"Sites.ReadWrite.All\",\n    \"Notes.Read.All\", \"Contacts.Read\", \"Chat.Read\", \"EWS.AccessAsUser.All\", \"full_access_as_user\",\n    \"Directory.ReadWrite.All\", \"User.ReadWrite.All\", \"RoleManagement.ReadWrite.Directory\",\n    \"Application.ReadWrite.All\", \"AppRoleAssignment.ReadWrite.All\"\n]);\n// Service principal object IDs your organization has already reviewed and approved\nlet approvedApps = dynamic([]);\nAuditLogs\n| where TimeGenerated > ago(lookback)\n| where OperationName == \"Consent to application\"\n| where Result =~ \"success\"\n| extend\n    AppName = tostring(TargetResources[0].displayName),\n    AppObjectId = tostring(TargetResources[0].id),\n    ConsentingUser = tostring(InitiatedBy.user.userPrincipalName),\n    ConsentingIP = tostring(InitiatedBy.user.ipAddress)\n| where AppObjectId !in (approvedApps)\n| mv-apply Prop = TargetResources[0].modifiedProperties on (\n    where tostring(Prop.displayName) == \"ConsentAction.Permissions\"\n    | project PermissionText = tostring(Prop.newValue)\n  )\n// newValue looks like: [[Id: ..., ConsentType: Principal, Scope: Mail.Read offline_access User.Read, ...]]\n| extend ScopeText = strcat_array(extract_all(@\"Scope:\\s*([^,\\]]+)\", PermissionText), \" \")\n| extend GrantedScopes = set_difference(split(ScopeText, \" \"), dynamic([\"\"]))\n| extend RiskyScopes = set_intersect(GrantedScopes, highRiskScopes)\n| where array_length(RiskyScopes) > 0\n| extend IsTenantWide = PermissionText has \"ConsentType: AllPrincipals\"\n| extend Severity = iff(IsTenantWide or array_length(RiskyScopes) >= 3, \"High\", \"Medium\")\n| project TimeGenerated, ConsentingUser, ConsentingIP, AppName, AppObjectId, IsTenantWide, RiskyScopes, GrantedScopes, Severity, CorrelationId",
